begin;
do $$
declare a uuid:='c0110000-0000-4000-8000-000000000001'; b uuid:='c0110000-0000-4000-8000-000000000002';
 root uuid; reply uuid; nested uuid; other uuid; result jsonb; entry jsonb;
begin
 insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
 (a,'conversation-a@example.invalid',now(),'{}','{}',now(),now()),(b,'conversation-b@example.invalid',now(),'{}','{}',now(),now());
 insert into public.feedback_members(user_id,display_name) values(a,'Conversation A'),(b,'Conversation B');
 perform set_config('request.jwt.claim.sub',a::text,true);
 root:=public.learn_comment('conversation-test','Conversation test','conversation-test','Existing clients can still post.');
 other:=public.learn_post('other-test','Other test','other-test','A different article.');
 perform set_config('request.jwt.claim.sub',b::text,true);
 reply:=public.learn_post('conversation-test','Conversation test','conversation-test','',root,'happy-frog');
 nested:=public.learn_post('conversation-test','Conversation test','conversation-test','A reply to the reply.',reply,null);
 begin perform public.learn_post('conversation-test','Conversation test','conversation-test','Wrong article.',other,null); raise exception 'TEST FAILED cross-article reply'; exception when others then if sqlerrm<>'learn_missing_comment' then raise; end if; end;
 begin perform public.learn_post('conversation-test','Conversation test','conversation-test','',root,'https://bad.invalid/a.gif'); raise exception 'TEST FAILED arbitrary GIF'; exception when others then if sqlerrm<>'learn_invalid_gif' then raise; end if; end;
 begin perform public.learn_post('conversation-test','Conversation test','conversation-test','',root,null); raise exception 'TEST FAILED empty comment'; exception when others then if sqlerrm<>'learn_comment_length' then raise; end if; end;
 perform public.learn_react(root,'love',true); perform public.learn_react(root,'love',true);
 perform public.learn_react(root,'frog',true);
 result:=public.learn_discussion('conversation-test');
 if jsonb_array_length(result)<>3 then raise exception 'TEST FAILED thread count'; end if;
 select value into entry from jsonb_array_elements(result) where value->>'id'=reply::text;
 if entry->>'parent_id'<>root::text or entry->>'gif_id'<>'happy-frog' then raise exception 'TEST FAILED reply metadata'; end if;
 select value into entry from jsonb_array_elements(result) where value->>'id'=root::text;
 if not exists(select 1 from jsonb_array_elements(entry->'reactions') r where r->>'kind'='love' and r->>'count'='1' and r->>'reacted'='true') then raise exception 'TEST FAILED idempotent personal reaction'; end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.learn_react(root,'love',true); perform public.learn_react(root,'love',false); perform public.learn_react(root,'love',false);
 if (select count(*) from public.learn_comment_reactions where comment_id=root and kind='love')<>1 then raise exception 'TEST FAILED removing another reader reaction'; end if;
 perform set_config('request.jwt.claim.sub','',true);
 result:=public.learn_discussion('conversation-test');
 if result::text like '%example.invalid%' or result::text like '%user_id%' or result::text like '%author_id%' then raise exception 'TEST FAILED private data leak'; end if;
 if exists(select 1 from jsonb_array_elements(result) c,jsonb_array_elements(c->'reactions') r where r->>'reacted'='true') then raise exception 'TEST FAILED anonymous personal reaction'; end if;
 begin perform public.learn_react(root,'love',true); raise exception 'TEST FAILED anonymous reaction'; exception when others then if sqlerrm<>'feedback_sign_in' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',b::text,true);
 begin perform public.learn_react(root,'unsupported',true); raise exception 'TEST FAILED arbitrary reaction'; exception when others then if sqlerrm<>'learn_invalid_reaction' then raise; end if; end;
 begin perform public.learn_moderate(root,'hide'); raise exception 'TEST FAILED unauthorized moderation'; exception when others then if sqlerrm<>'feedback_admin_only' then raise; end if; end;
 insert into public.feedback_admins(user_id) values(b);
 perform public.learn_moderate(root,'hide');
 if jsonb_array_length(public.learn_discussion('conversation-test'))<>0 then raise exception 'TEST FAILED hidden ancestor leaked replies'; end if;
 begin perform public.learn_post('conversation-test','Conversation test','conversation-test','Hidden reply.',reply,null); raise exception 'TEST FAILED reply to hidden thread'; exception when others then if sqlerrm<>'learn_missing_comment' then raise; end if; end;
 begin perform public.learn_react(reply,'love',true); raise exception 'TEST FAILED reaction on hidden thread'; exception when others then if sqlerrm<>'learn_missing_comment' then raise; end if; end;
 perform public.learn_moderate(root,'restore');
 if jsonb_array_length(public.learn_discussion('conversation-test'))<>3 then raise exception 'TEST FAILED restore thread'; end if;
 perform public.learn_report(reply,'Other','Testing a report on a reply without hiding it.');
 if not exists(select 1 from jsonb_array_elements(public.learn_moderation()->'reports') r where r->>'comment_id'=reply::text) then raise exception 'TEST FAILED reply report'; end if;
 perform public.learn_post('conversation-test','Conversation test','conversation-test',repeat('🩵',2000),null,null);
 begin perform public.learn_post('conversation-test','Conversation test','conversation-test','Fourth in ten minutes.',null,null); raise exception 'TEST FAILED posting rate limit'; exception when others then if sqlerrm<>'learn_comment_limit' then raise; end if; end;
 update public.feedback_members set blocked=true where user_id=a;
 perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.learn_react(root,'love',true); raise exception 'TEST FAILED blocked reaction'; exception when others then if sqlerrm<>'feedback_blocked' then raise; end if; end;
 if has_table_privilege('authenticated','public.learn_comment_reactions','INSERT') or has_table_privilege('anon','public.learn_comment_reactions','SELECT') then raise exception 'TEST FAILED direct reaction access'; end if;
 if has_function_privilege('anon','public.learn_post(text,text,text,text,uuid,text)','EXECUTE') or has_function_privilege('anon','public.learn_react(uuid,text,boolean)','EXECUTE') or has_function_privilege('authenticated','public.learn_comment_visible(uuid)','EXECUTE') then raise exception 'TEST FAILED RPC privileges'; end if;
end $$;
select 'PASS: old clients, threaded/GIF replies, reaction ownership/idempotence, public privacy, moderation/restore, blocked users, limits, and RLS. All test rows roll back.' as conversation_checks;
rollback;
